const body = $input.first().json.body || $input.first().json;

// Parse rawRequest JSON - most reliable source from Jotform
let raw = {};
try {
  raw = JSON.parse(body.rawRequest || '{}');
} catch (e) {
  raw = {};
}

const submissionId = 'CAMP-' + Date.now();

// Extract metadata from rawRequest
const requesterEmail = String(raw['q3_q3_email1'] || '')
  .replace(/^PW Official Email:/i, '')
  .trim();

const requesterNameObj = raw['q4_q4_fullname2'] || {};
const requesterName = `${requesterNameObj.first || ''} ${requesterNameObj.last || ''}`.trim() || 'Unknown';

const team = raw['q5_q5_dropdown3'] || '';
const approverEmail = String(raw['q6_q6_email4'] || '').trim();
const commType = raw['q7_q7_dropdown5'] || 'Utility';
const channel = raw['q8_q8_dropdown6'] || 'WhatsApp';
const templateName = raw['q9_q9_dropdown7'] || '';

const audienceCount = raw['q20_q20_number18'] || '0';
const additionalInstructions = raw['q23_q23_textarea21'] || '';
const department = '';
const dataType = 'Phone Numbers';

// Audience file link
let audienceFileLink = raw['q19_q19_textarea17'] || raw['q19_q19_textbox17'] || '';
audienceFileLink = String(audienceFileLink).trim();

// Convert Google Sheets link to CSV export URL and preserve gid
if (audienceFileLink.includes('spreadsheets/d/')) {
  const sheetIdMatch = audienceFileLink.match(/spreadsheets\/d\/([a-zA-Z0-9_-]+)/);
  const gidMatch = audienceFileLink.match(/[?&]gid=([0-9]+)/);

  if (sheetIdMatch) {
    const sheetId = sheetIdMatch[1];
    const gid = gidMatch ? gidMatch[1] : '0';
    audienceFileLink = `https://docs.google.com/spreadsheets/d/${sheetId}/export?format=csv&gid=${gid}`;
  }
}

// Convert Google Drive file link to direct download URL
else if (audienceFileLink.includes('drive.google.com')) {
  const match1 = audienceFileLink.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
  const match2 = audienceFileLink.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  const match3 = audienceFileLink.match(/\/d\/([a-zA-Z0-9_-]+)/);

  const fileId = (match1 || match2 || match3 || [])[1];

  if (fileId) {
    audienceFileLink = `https://drive.google.com/uc?export=download&id=${fileId}`;
  }
}

// Scheduled date
const scheduledDateObj = raw['q21_q21_datetime19'] || {};
const scheduledDate = scheduledDateObj.month && scheduledDateObj.day && scheduledDateObj.year
  ? `${String(scheduledDateObj.month).padStart(2, '0')} ${String(scheduledDateObj.day).padStart(2, '0')} ${scheduledDateObj.year}`
  : '';

// Scheduled time
const scheduledTimeObj = raw['q22_q22_time20'] || {};
const scheduledTimeRaw = scheduledTimeObj.timeInput || '';
const scheduledAmPm = scheduledTimeObj.ampm || '';

// Build scheduled datetime with IST handling
let scheduledAt;

if (scheduledDate && scheduledTimeRaw) {
  let [hours, minutes] = scheduledTimeRaw.split(':').map(Number);

  if (scheduledAmPm === 'PM' && hours !== 12) hours += 12;
  if (scheduledAmPm === 'AM' && hours === 12) hours = 0;

  const hh = String(hours).padStart(2, '0');
  const mm = String(minutes || 0).padStart(2, '0');

  scheduledAt = `${scheduledDate} ${hh}:${mm} IST`;
} else {
  scheduledAt = new Date(Date.now() + 30 * 60 * 1000).toISOString();
}

// Template mapping
// Important: variables are NOT taken from Jotform now.
// requiredColumns defines what the uploaded CSV/sheet must contain.
const templateMapping = {
  'Activity Reminder': {
    campaignName: 'generic_activity_reminder',
    requiredColumns: ['phone', 'var1', 'var2', 'var3', 'var4', 'var5', 'var6', 'var7'],
    samplePreview: `Dear Parent,

This is to inform you that Parent Teacher Meeting has been scheduled.

Date: 10 June 2026
Time: 4:00 PM
Location/Mode: Noida Vidyapeeth

Please attend on time.

Thanks,
PW Vidyapeeth`
  },

  'Payment Reminder': {
    campaignName: 'generic_payment_reminder',
    requiredColumns: ['phone', 'var1', 'var2', 'var3', 'var4', 'var5', 'var6'],
    samplePreview: `Dear Student,

This is a reminder that your EMI payment for Course is pending.

Please complete the payment by 10 June 2026.

For queries, contact support.

Thanks,
PW`
  },

  'Info Update': {
    campaignName: 'generic_info_update',
    requiredColumns: ['phone', 'var1', 'var2', 'var3', 'var4'],
    samplePreview: `Dear Student,

This is to inform you that your update is available.

Please check your PW App for details.

Thanks,
PW`
  },

  'Test/Result Update': {
    campaignName: 'generic_test_result_update',
    requiredColumns: ['phone', 'var1', 'var2', 'var3', 'var4', 'var5', 'var6', 'var7'],
    samplePreview: `Dear Parent,

This is to inform you that the test result is available.

Assessment: Weekly Test
Date: 10 June 2026
Details: Please check the PW App.

For queries contact support.

Thanks,
PW Vidyapeeth`
  },

  'Order/Service Update': {
    campaignName: 'generic_order_service_update',
    requiredColumns: ['phone', 'var1', 'var2', 'var3', 'var4', 'var5'],
    samplePreview: `Dear Student,

This is to inform you that your order status has been updated.

Order/Request Details: Sample Order ID

Next Step: Please confirm your details.

Thanks,
PhysicsWallah`
  }
};

const tmpl = templateMapping[templateName] || null;

// Map team to WABA
const wabaMapping = {
  'Vidyapeeth (Marketing)': { userName: 'PW VP', wabaNumber: '919319294193' },
  'Vidyapeeth (Marketing Utility)': { userName: 'PW VP', wabaNumber: '919319294193' },
  'Vidyapeeth (Ops)': { userName: 'PW VP', wabaNumber: '919319294193' },

  'ECOM': { userName: 'PhysicsWallah', wabaNumber: '918130960280' },

  'Pw Skills': { userName: 'PhysicsWallah', wabaNumber: '918130960280' },
  'PW Skills': { userName: 'PhysicsWallah', wabaNumber: '918130960280' },
  'Pw Skills Ops': { userName: 'PhysicsWallah', wabaNumber: '918130960280' },
  'PW Skills Ops': { userName: 'PhysicsWallah', wabaNumber: '918130960280' },

  'PW Tuition centre': { userName: 'PW Tuition Center', wabaNumber: '919599368942' },
  'PW Tuition Centre': { userName: 'PW Tuition Center', wabaNumber: '919599368942' }
};

const defaultWaba = { userName: 'PhysicsWallah', wabaNumber: '918130960280' };
const waba = wabaMapping[team] || defaultWaba;

let campaignName = '';
let templateParams = [];
let messagePreview = '';
let status = 'Pending';

if (tmpl) {
  campaignName = tmpl.campaignName;

  // Temporary storage: required CSV columns.
  // Actual templateParams will be generated row-wise from CSV later.
  templateParams = tmpl.requiredColumns;

  messagePreview = `${tmpl.samplePreview}

Required CSV columns:
${tmpl.requiredColumns.join(', ')}`;
} else {
  status = 'Validation Failed';
  messagePreview = `Unsupported template selected: ${templateName}. This request needs manual review.`;
}

return [{
  json: {
    submissionId,
    requesterName,
    requesterEmail,
    approverEmail,
    team,
    department,
    commType,
    channel,
    dataType,
    audienceFileLink,
    audienceCount,
    scheduledAt,
    templateName,
    campaignName,
    templateParams: JSON.stringify(templateParams),
    messagePreview,
    userName: waba.userName,
    wabaNumber: waba.wabaNumber,
    additionalInstructions,
    status,
    submittedAt: new Date().toISOString()
  }
}];

const now = new Date();
const dueCampaigns = [];

for (const item of $input.all()) {
  const row = item.json;
  if (!row['scheduledAt']) continue;

    // Skip if already processed
  if (['Sent', 'Processing', 'Rejected'].includes(row['status'])) continue;

  // Parse "06 05 2026 16:55 IST" → compare with current IST time
  const rawTime = row['scheduledAt'].replace(' IST', '').trim();
  // rawTime = "06 05 2026 16:55"
  const parts = rawTime.split(' ');
  // parts = ["06", "05", "2026", "16:55"]
  const month = parseInt(parts[0]) - 1;
  const day = parseInt(parts[1]);
  const year = parseInt(parts[2]);
  const [hours, minutes] = parts[3].split(':').map(Number);

  // Create date in IST (UTC+5:30)
  const scheduledUTC = new Date(Date.UTC(year, month, day, hours - 5, minutes - 30));

  const diffMinutes = (now - scheduledUTC) / (1000 * 60);

  if (diffMinutes >= 0 && diffMinutes <= 10) {
    dueCampaigns.push({ json: row });
  }
}

if (dueCampaigns.length === 0) {
  return [{ json: { skip: true, message: 'No campaigns due' } }];
}

// MVP safety: process only one due campaign per schedule run.
// This prevents downstream nodes using .first() from mixing campaign context.
return [dueCampaigns[0]];

const row = $('Filter Due Campaigns').first().json;

const fileLink = String(row['audienceFileLink'] || '').trim();

if (!fileLink) {
  throw new Error(`Audience file link missing for submissionId: ${row['submissionId'] || 'unknown'}`);
}

return [{
  json: {
    ...row,
    audienceFileUrl: fileLink,
    readyToFetch: true
  }
}];

const csvText = $input.first().json.data || $input.first().json.body || '';

// Get campaign data from due campaign row
const campaignData = $('Filter Due Campaigns').first().json;

// -----------------------------
// 1. Basic CSV parser
// -----------------------------

function parseCsvLine(line) {
  const result = [];
  let current = '';
  let insideQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const nextChar = line[i + 1];

    if (char === '"' && insideQuotes && nextChar === '"') {
      current += '"';
      i++;
    } else if (char === '"') {
      insideQuotes = !insideQuotes;
    } else if (char === ',' && !insideQuotes) {
      result.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }

  result.push(current.trim());
  return result;
}

const lines = csvText
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

if (lines.length < 2) {
  throw new Error('Audience CSV is empty or missing data rows.');
}

const headers = parseCsvLine(lines[0]).map(h =>
  h.trim().toLowerCase().replace(/\s+/g, '')
);

// -----------------------------
// 2. Required columns from templateParams
// In Parse Submission, templateParams now stores required columns
// Example: ["phone","var1","var2","var3","var4","var5","var6","var7"]
// -----------------------------

let requiredColumns = [];

try {
  requiredColumns = JSON.parse(campaignData['templateParams'] || '[]');
} catch (e) {
  requiredColumns = [];
}

requiredColumns = requiredColumns.map(c =>
  String(c).trim().toLowerCase().replace(/\s+/g, '')
);

if (!requiredColumns.length) {
  throw new Error('Required CSV columns not found in campaign templateParams.');
}

const missingColumns = requiredColumns.filter(col => !headers.includes(col));

if (missingColumns.length) {
  throw new Error(`Audience CSV missing required columns: ${missingColumns.join(', ')}`);
}

// -----------------------------
// 3. Column index map
// -----------------------------

const colIndex = {};
headers.forEach((header, index) => {
  colIndex[header] = index;
});

// -----------------------------
// 4. Phone normalization
// -----------------------------

function normalizePhone(value) {
  let mobile = String(value || '').replace(/[^0-9]/g, '');

  if (!mobile) return '';

  if (mobile.length === 10) {
    mobile = '91' + mobile;
  }

  if (mobile.length === 13 && mobile.startsWith('091')) {
    mobile = mobile.substring(1);
  }

  if (mobile.length === 12 && mobile.startsWith('91')) {
    return mobile;
  }

  return '';
}

// -----------------------------
// 5. Build row-wise AiSensy payload items
// -----------------------------

const output = [];
const seen = new Set();

for (let i = 1; i < lines.length; i++) {
  const values = parseCsvLine(lines[i]);

  const phoneRaw = values[colIndex.phone];
  const destination = normalizePhone(phoneRaw);

  if (!destination) continue;
  if (seen.has(destination)) continue;

  seen.add(destination);

  const varColumns = requiredColumns.filter(col => col !== 'phone');

  const templateParams = varColumns.map(col => {
    const index = colIndex[col];
    return values[index] !== undefined ? String(values[index]).trim() : '';
  });

  // Do not send if any required variable is blank
  const hasBlankRequiredVar = templateParams.some(v => !v);

  if (hasBlankRequiredVar) {
    continue;
  }

  output.push({
    json: {
      destination,
      campaignName: campaignData['campaignName'] || '',
      userName: campaignData['userName'] || '',
      templateParams,
      submissionId: campaignData['submissionId'] || '',
      requesterEmail: campaignData['requesterEmail'] || '',
      requesterName: campaignData['requesterName'] || '',
      team: campaignData['team'] || ''
    }
  });
}

if (!output.length) {
  throw new Error('No valid audience rows found after phone and variable validation.');
}

// Phase 1 cap
return output.slice(0, 50000);

// Aggregate results and check for errors
const results = $input.all();
const submissionId = $('Filter Due Campaigns').first().json['submissionId'] || '';

const total = results.length;
const errors = results.filter(r => r.json.error || r.json.status === 'failed').length;
const sent = total - errors;

return [{
  json: {
    submissionId,
    totalSent: sent,
    totalErrors: errors,
    total,
    completedAt: new Date().toISOString(),
    status: errors === 0 ? 'Sent' : 'Sent with Errors'
  }
}];
